function formatDate(dateStr) {
  if (!dateStr || dateStr === '-') return '-';
  try {
    const d = new Date(dateStr);
    return d.toLocaleDateString('id-ID', {day:'numeric', month:'long', year:'numeric'});
  } catch(e) { return dateStr; }
}

function deadlineNextMonthSix(startDate) {
  if (!startDate) return '';
  const d = new Date(startDate + 'T00:00:00');
  const deadline = new Date(d.getFullYear(), d.getMonth() + 1, 6);
  return `${deadline.getFullYear()}-${String(deadline.getMonth() + 1).padStart(2, '0')}-06`;
}

function badgeStatus(status) {
  const s = String(status || '').toLowerCase();
  if (s.includes('sudah') || s.includes('aktif') || s.includes('valid') || s.includes('closed') || s.includes('rendah')) return 'success';
  if (s.includes('belum') || s.includes('open') || s.includes('pending') || s.includes('draft')) return 'warning';
  if (s.includes('tinggi') || s.includes('danger')) return 'danger';
  if (s.includes('sedang') || s.includes('medium') || s.includes('proses')) return 'medium';
  return 'muted';
}

function showToast(msg) {
  const t = document.createElement('div');
  t.className = 'toast';
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 3000);
}

function downloadCsv(filename, rows) {
  if (!rows || !rows.length) return showToast('Tidak ada data untuk diexport');
  const headers = Object.keys(rows[0]);
  const csv = [headers.join(','), ...rows.map(r => headers.map(h => {
    let v = r[h] ?? '';
    if (typeof v === 'object') v = JSON.stringify(v);
    return '"' + String(v).replace(/"/g, '""') + '"';
  }).join(','))].join('\n');
  const blob = new Blob([csv], {type:'text/csv'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
}


async function requestApi(action, payload = {}) {
  await new Promise(r => setTimeout(r, 300));

  switch(action) {
    case 'getEmployees':
      return JSON.parse(JSON.stringify(NGINGETKEN_DATA.employees));

    case 'getPeriods':
      return JSON.parse(JSON.stringify(NGINGETKEN_DATA.periods));

    case 'getActivePeriod': {
      const active = NGINGETKEN_DATA.periods.find(p => p.status === 'Aktif');
      return JSON.parse(JSON.stringify(active || NGINGETKEN_DATA.periods[4]));
    }

    case 'getDashboardData':
      return JSON.parse(JSON.stringify({
        activePeriod: NGINGETKEN_DATA.activePeriod,
        summary: NGINGETKEN_DATA.summary,
        monitoring: NGINGETKEN_DATA.monitoring,
        byUnit: NGINGETKEN_DATA.byUnit,
        followups: NGINGETKEN_DATA.followups,
        riskSummary: NGINGETKEN_DATA.riskSummary
      }));

    case 'getExecutiveSummary':
      return JSON.parse(JSON.stringify({
        activePeriod: NGINGETKEN_DATA.activePeriod,
        summary: NGINGETKEN_DATA.summary,
        byUnit: NGINGETKEN_DATA.byUnit
      }));

    case 'getFollowUps':
      return JSON.parse(JSON.stringify(NGINGETKEN_DATA.followups));

    case 'getAuditLogs':
      return JSON.parse(JSON.stringify(NGINGETKEN_DATA.auditLogs));

    case 'getEmployeeHistory': {
      const { pegawai_id, nama } = payload;
      let targetId = pegawai_id;
      if (!targetId && nama) {
        const emp = NGINGETKEN_DATA.employees.find(e => e.nama.toLowerCase() === nama.toLowerCase());
        if (emp) targetId = emp.pegawai_id;
      }
      const employee = NGINGETKEN_DATA.employees.find(e => e.pegawai_id === targetId);
      const empResponses = NGINGETKEN_DATA.responses.filter(r => r.pegawai_id === targetId);
      return { employee: employee || null, responses: empResponses, followups: [] };
    }

    case 'lookupEmployeeHistory': {
      const lookupName = payload.nama || '';
      const foundEmp = NGINGETKEN_DATA.employees.find(e => 
        e.nama.toLowerCase() === lookupName.toLowerCase() ||
        lookupName.toLowerCase().includes(e.nama.toLowerCase()) ||
        e.nama.toLowerCase().includes(lookupName.toLowerCase())
      );
      if (!foundEmp) throw new Error('Pegawai tidak ditemukan');
      const lastRsp = NGINGETKEN_DATA.responses
        .filter(r => r.pegawai_id === foundEmp.pegawai_id)
        .sort((a,b) => new Date(b.waktu_submit) - new Date(a.waktu_submit))[0];
      return {
        employee: foundEmp,
        lastResponse: lastRsp || null,
        message: lastRsp ? 'Histori ditemukan' : 'Belum ada histori pengisian'
      };
    }

    case 'submitHtmlForm': {
      const { response } = payload;
      const newId = 'R' + String(NGINGETKEN_DATA.responses.length + 1).padStart(3, '0');
      const newResponse = {
        response_id: newId,
        periode_id: response.periode_id,
        periode_bulan: response.periode_bulan,
        pegawai_id: response.pegawai_id || null,
        nama: response.nama,
        unit: response.unit,
        waktu_submit: new Date().toISOString().replace('T',' ').slice(0,19),
        answers: response.answers,
        answer_json: JSON.stringify(response.answers),
        salinan_pernyataan: response.salinan_pernyataan,
        catatan: response.catatan || '',
        status_validasi: 'Valid',
        integrity_score: 100,
        risk_level: 'Rendah'
      };
      const yaCount = Object.values(response.answers).filter(v => v === 'Ya').length;
      const raguCount = Object.values(response.answers).filter(v => v === 'Ragu-ragu').length;
      if (yaCount > 0) { newResponse.risk_level = 'Tinggi'; newResponse.integrity_score = Math.max(0, 100 - yaCount * 25); }
      else if (raguCount > 0) { newResponse.risk_level = 'Sedang'; newResponse.integrity_score = 85; }

      NGINGETKEN_DATA.responses.push(newResponse);
      const monIdx = NGINGETKEN_DATA.monitoring.findIndex(m => m.nama.toLowerCase() === response.nama.toLowerCase());
      if (monIdx >= 0) {
        NGINGETKEN_DATA.monitoring[monIdx].status_pengisian = 'Sudah Mengisi';
        NGINGETKEN_DATA.monitoring[monIdx].waktu_submit = newResponse.waktu_submit;
        NGINGETKEN_DATA.monitoring[monIdx].integrity_score = newResponse.integrity_score;
        NGINGETKEN_DATA.monitoring[monIdx].risk_level = newResponse.risk_level;
      }
      NGINGETKEN_DATA.summary.submitted = NGINGETKEN_DATA.monitoring.filter(m => m.status_pengisian === 'Sudah Mengisi').length;
      NGINGETKEN_DATA.summary.pending = NGINGETKEN_DATA.summary.total - NGINGETKEN_DATA.summary.submitted;
      NGINGETKEN_DATA.summary.percentage = Math.round(NGINGETKEN_DATA.summary.submitted / NGINGETKEN_DATA.summary.total * 100);
      return { status: 'success', response_id: newId, ...newResponse };
    }

    case 'createFollowUp': {
      const { followup } = payload;
      const fuId = 'FU' + String(NGINGETKEN_DATA.followups.length + 1).padStart(3, '0');
      const newFu = {
        followup_id: fuId,
        pegawai_id: followup.pegawai_id || '',
        nama: followup.nama || '',
        periode_id: followup.periode_id || '',
        prioritas: followup.prioritas || 'Medium',
        status: followup.status || 'Open',
        catatan: followup.catatan || '',
        created_at: new Date().toISOString().replace('T',' ').slice(0,19)
      };
      NGINGETKEN_DATA.followups.push(newFu);
      return newFu;
    }

    case 'updateFollowUp': {
      const { followup_id, status: fuStatus } = payload;
      const fuIdx = NGINGETKEN_DATA.followups.findIndex(f => f.followup_id === followup_id);
      if (fuIdx >= 0) NGINGETKEN_DATA.followups[fuIdx].status = fuStatus;
      return { success: true };
    }

    case 'createEmployee': {
      const { employee } = payload;
      const newEmpId = 'P' + String(NGINGETKEN_DATA.employees.length + 1).padStart(3, '0');
      const newEmp = { pegawai_id: newEmpId, nama: employee.nama || '', unit: employee.unit || '', status_aktif: employee.status_aktif !== false };
      NGINGETKEN_DATA.employees.push(newEmp);
      return newEmp;
    }

    case 'createPeriod': {
      const { period } = payload;
      const newPerId = 'PRD' + String(NGINGETKEN_DATA.periods.length + 1).padStart(3, '0');
      const newPer = { ...period, tanggal_deadline: deadlineNextMonthSix(period.tanggal_mulai), periode_id: newPerId };
      NGINGETKEN_DATA.periods.push(newPer);
      return newPer;
    }

    case 'setupDatabase':
      return { message: 'Database sudah siap dengan data nyata dari Excel (42 pegawai, 241 histori)' };

    default:
      throw new Error('Action tidak dikenal: ' + action);
  }
}
